export type ToolEntry = {
  name: string;
  title: string;
  /** The tool only reads: nothing is changed or made. */
  readOnly: boolean;
  /** always: runs as a job; sometimes: short calls answer at once; never: answers at once. */
  longRunning: 'always' | 'sometimes' | 'never';
};

